function seatsFor(fr){const by={};D.citizens.forEach((c,i)=>{if(fr.at[i]==null)return;(by[fr.at[i]]=by[fr.at[i]]||[]).push(i)});const out={};for(const loc in by){const idx=by[loc].slice().sort((a,b)=>Number(D.citizens[b].named)-Number(D.citizens[a].named)||a-b);const P=LP[loc]||{x:MW/2,y:MH/2};let k=0,ring=0;while(k<idx.length){const cap=ring===0?1:ring*6;const n=Math.min(cap,idx.length-k);for(let j=0;j<n;j++,k++){const a=(j/n)*2*Math.PI+ring*0.6;out[idx[k]]={x:P.x+Math.cos(a)*ring*20,y:P.y+8+Math.sin(a)*ring*11}}ring++}}return out}
