export function renderGallery(runs: { dir: string; r: Record_ }[]): string {
  const roots = runs.filter((x) => !x.r.parent), byParent = new Map<string, typeof runs>();
  for (const x of runs.filter((x) => x.r.parent)) { const k = x.r.parent!.lineage?.[0] ?? x.r.parent!.runId; (byParent.get(k) ?? byParent.set(k, []).get(k)!).push(x); }
  const ordered = [...roots.sort((a, b) => a.r.title.localeCompare(b.r.title) || a.r.seed - b.r.seed).flatMap((x) => [x, ...(byParent.get(x.r.runId) ?? []).sort((a, b) => a.dir.localeCompare(b.dir))]), ...runs.filter((x) => x.r.parent && !roots.some((rt) => rt.r.runId === (x.r.parent!.lineage?.[0] ?? x.r.parent!.runId)))];
  const cut = (s: string, n: number) => s.length <= n ? s : s.slice(0, n).replace(/\s+\S*$/, "") + "…";
  const cards = ordered.map(({ dir, r }) => {
    const total = Object.values(r.outcome).reduce((a, b) => a + b, 0);
    const bars = r.ending.choices.map((c, i) => `<div class="bar"><span class="small">${esc(c.label)}</span><span><i style="width:${Math.round(((r.outcome[c.id] ?? 0) / total) * 100)}%;background:var(--acc${i ? i + 1 : ""})"></i></span><span class="small">${r.outcome[c.id] ?? 0}</span></div>`).join("");
    return `<a class="card${r.parent ? " fork" : ""}" href="${esc(dir)}/index.html" title="${esc(r.parent?.change ?? "")}"><b>${esc(r.title)}</b> <span class="mute">seed ${r.seed} · ${esc(r.brain)}${r.parent ? " · fork" : ""}</span><div class="small mute"><code>${esc(dir)}</code></div><div class="bars">${bars}</div><div class="small mute">${r.citizens.length} citizens · ${r.beats.filter((b) => b.level >= 2).length} beats${r.parent ? `<br>↳ ${esc(cut(r.parent.change, 110))}${r.parent.firstDivergence !== null ? ` · splits at h${r.parent.firstDivergence}` : ""}` : ""}</div></a>`;
  }).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Uncanny Valley — worlds</title><style>${CSS}</style></head><body><main><h1>Uncanny Valley</h1><p class="premise">Finite worlds. Every one ends; every one is on record.</p><div class="gallery grid2">${cards || "<p>No archives yet — run <code>pnpm world last-ferry --seed 7</code>.</p>"}</div></main></body></html>`;
}

/** Write index.html into one archive dir, or into every archive dir plus the gallery. */
export function buildSite(target?: string, root = "archive"): string[] {
  const dirs = target ? [existsSync(target) ? target : join(root, target)] : readdirSync(root).map((d) => join(root, d)).filter((d) => existsSync(join(d, "record.json")));
  const written: string[] = [];
  const runs: { dir: string; r: Record_ }[] = [];
  for (const d of dirs) {
    if (!existsSync(join(d, "record.json"))) throw new Error(`no record.json in ${d}`);
    const r = JSON.parse(readFileSync(join(d, "record.json"), "utf8")) as Record_;
    writeFileSync(join(d, "index.html"), renderWorldPage(r, { forkMd: existsSync(join(d, "fork.md")) ? "fork.md" : undefined }));
    written.push(join(d, "index.html")); runs.push({ dir: d.split("/").pop()!, r });
  }
  if (!target) { const all = readdirSync(root).map((d) => join(root, d)).filter((d) => existsSync(join(d, "record.json"))).map((d) => ({ dir: d.split("/").pop()!, r: JSON.parse(readFileSync(join(d, "record.json"), "utf8")) as Record_ })); writeFileSync(join(root, "index.html"), renderGallery(all)); written.push(join(root, "index.html")); }
  return written;
}
